-- Dumping structure for table logistics_system.cn_batches
CREATE TABLE IF NOT EXISTS `cn_batches` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `batch_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Format: QC-DDMMYYYY-N',
  `warehouse_id` bigint unsigned NOT NULL,
  `destination_warehouse_name` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `total_packages` int DEFAULT '0',
  `total_weight` decimal(10,2) DEFAULT '0.00',
  `actual_batch_weight` decimal(10,2) DEFAULT NULL,
  `package_material_weight` decimal(10,2) DEFAULT NULL,
  `actual_length` decimal(10,2) DEFAULT NULL,
  `actual_width` decimal(10,2) DEFAULT NULL,
  `actual_height` decimal(10,2) DEFAULT NULL,
  `actual_volume` decimal(12,4) DEFAULT NULL,
  `carrier_name` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `transport_code` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `route_name` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `vehicle_plate` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `driver_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `driver_phone` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `freight_cost` decimal(14,2) DEFAULT NULL,
  `handed_over_by` bigint unsigned DEFAULT NULL,
  `handed_over_at` datetime DEFAULT NULL,
  `dispatch_snapshot` json DEFAULT NULL,
  `dispatch_note` text COLLATE utf8mb4_unicode_ci,
  `status` enum('pending','exporting','arrived_vn','completed','cancelled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `shipping_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'normal',
  `packaging_type` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `transport_container_count` int unsigned DEFAULT NULL,
  `departed_at` datetime DEFAULT NULL,
  `expected_arrival_at` datetime DEFAULT NULL,
  `arrived_at` datetime DEFAULT NULL,
  `note` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `batch_code` (`batch_code`),
  KEY `warehouse_id` (`warehouse_id`),
  KEY `idx_batch_code` (`batch_code`),
  KEY `idx_status` (`status`),
  CONSTRAINT `cn_batches_ibfk_1` FOREIGN KEY (`warehouse_id`) REFERENCES `cn_warehouses` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=945 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

