CREATE TABLE IF NOT EXISTS `order_items` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_id` bigint unsigned NOT NULL,
  `product_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `product_link` text COLLATE utf8mb4_unicode_ci,
  `price_cny` decimal(10,2) NOT NULL COMMENT 'Price in Chinese Yuan',
  `exchange_rate` decimal(15,4) DEFAULT NULL,
  `unit_price_vnd` decimal(18,0) NOT NULL DEFAULT '0',
  `quantity` int NOT NULL DEFAULT '1',
  `subtotal_cny` decimal(15,2) NOT NULL DEFAULT '0.00',
  `subtotal_vnd` decimal(18,0) NOT NULL DEFAULT '0',
  `note` text COLLATE utf8mb4_unicode_ci,
  `tracking_number` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Tracking number after purchase',
  `product_image` text COLLATE utf8mb4_unicode_ci COMMENT 'Product image URL',
  `seller` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `shop_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `shop_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `size` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `color` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `order_id` (`order_id`),
  CONSTRAINT `order_items_ibfk_1` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE
